css:
.trial-cooking-sheet {
    font-family: Arial, sans-serif;
    font-size: 10.5pt;
    color: #111;
}

.print-header {
    text-align: center;
    margin-bottom: 14px;
    padding-bottom: 8px;
    border-bottom: 2px solid #000;
    background: #fff;
}

.print-header h2 {
    margin: 0 0 4px 0;
    font-size: 18pt;
}

.table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 14px;
}

.table-bordered th,
.table-bordered td {
    border: 1px solid #000 !important;
    padding: 6px;
    vertical-align: top;
}

.table-bordered th {
    background: #f0f0f0 !important;
    font-weight: 700;
}

.trial-meta th {
    width: 16%;
}

.trial-meta td {
    width: 34%;
}

.section-block {
    margin-top: 12px;
}

.section-block h3 {
    margin: 0 0 7px 0;
    padding-bottom: 4px;
    border-bottom: 1px solid #000;
    font-size: 13pt;
}

.meta-block,
.solid-liquid-block {
    page-break-inside: avoid;
}

.table tr {
    page-break-inside: avoid;
}

.compact-table {
    font-size: 8.5pt;
}

.compact-table th,
.compact-table td {
    padding: 4px;
}

.num {
    text-align: right;
}

.footer-lines {
    margin-top: 18px;
}

.footer-lines div {
    min-height: 20px;
    margin: 12px 0;
    padding-bottom: 4px;
    border-bottom: 1px solid #777;
}

.no-run-message {
    padding: 24px;
    border: 1px dashed #a00;
    color: #a00;
    text-align: center;
    font-size: 12pt;
}

@media print {
    .print-header {
        margin-top: 0;
    }

    * {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
        box-shadow: none !important;
        text-shadow: none !important;
    }
}
